entries[397532] = { ["name"] = "Ureinklang", ["text"] = "Unbegrenzte Reichweite\nSofort\nBei voller Energie ist Kurog perfekt auf die Urelemente abgestimmt, sodass er alle Altarfähigkeiten gleichzeitig erlangt. Zusätzlich wogt Grimmtotem vor Elementarenergie und verursacht alle 0.5 Sek. 42398 Elementarschaden. Dieser Effekt ist stapelbar." }
