entries[397718] = { ["name"] = "Flammendes Inferno", ["text"] = "200 Meter Reichweite\nSofort\nDer flammengeschmiedete Vernichter entzündet Magmapfütze n im Raum und erschafft so ' Flammendes Inferno '.\n\nSpielercharaktere im Effektbereich von Flammendes Inferno erleiden alle 1 Sek. 60063 Feuerschaden und lassen seine Flammen schwinden. Nach 15 Sek. erscheint pro ' Flammendes Inferno ' eine schwelende Ausgeburt." }
