entries[397853] = { ["name"] = "Beeindruckende stahlgeschmiedete Essenz", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtstahlbarren (100), Wildblut (25), Echteisenerz (20)\nVerkäufer:\nNonn Drillingsratsche\nZone:\nKriegsspeer\nKosten:\n5\n\nVerkäufer:\nRoyce Großbart\nZone:\nSturmschild\nKosten:\n5\n\nBeeindruckende stahlgeschmiedete Essenz\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Verändert das Aussehen einer mit der Schmiedekunst von Draenor hergestellten Waffe und lässt sie beeindruckender werden.\nBenutzbar mit: Mit der Schmiedekunst von Draenor hergestellte Waffen." }
entries[397855] = { ["name"] = "Außergewöhnliche stahlgeschmiedete Essenz", ["text"] = "Wirken in 3.5 sek.\nTools: Schmiedehammer\nReagenzien:\nEchtstahlbarren (125), Teufelsfäule (35), Echteisenerz (20)\nVerkäufer:\nNonn Drillingsratsche\nZone:\nKriegsspeer\nKosten:\n5\n\nVerkäufer:\nRoyce Großbart\nZone:\nSturmschild\nKosten:\n5\n\nAußergewöhnliche stahlgeschmiedete Essenz\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Verändert das Aussehen einer mit der Schmiedekunst von Draenor hergestellten Waffe und lässt sie wahrlich außergewöhnlich werden.\nBenutzbar mit: Mit der Schmiedekunst von Draenor hergestellte Waffen." }
